mapper.select:
select a.id, a.team_id, a.schedule_item_id, a.index_order, a.back_number, a.match_id, a.game_item_id, a.sport_limit, a.works_name, a.works_music, a.works_music_name, a.works_video, a.create_time, a.update_time, b.id as sub_id, b.match_id as sub_match_id, b.sport_id as sub_sport_id, b.sign_record_id as sub_sign_record_id, cc.player_name, cc.id_card, cc.sex, jt.team_name, jst.schedule_info_id, jst.schedule_place_id, jst.item_name, jst.shcedule_time, jst.area from jw_sign_record a left join jw_sign_record_sport b on b.sign_record_id = a.id left join jw_sport cc on cc.id = b.sport_id left join jw_team jt on jt.id = a.team_id left join jw_schedule_item jst on jst.id = a.schedule_item_id
and a.schedule_item_id = #{scheduleItemId} and a.game_item_id = #{gameItemId}
order by jt.id

select a.id, a.team_id, a.schedule_item_id, a.index_order, a.back_number, a.match_id, a.game_item_id, a.sport_limit, a.works_name, a.works_music, a.works_music_name, a.works_video,
a.create_time, a.update_time, b.id as sub_id, b.match_id as sub_match_id, b.sport_id as sub_sport_id, b.sign_record_id as sub_sign_record_id,
cc.player_name, cc.id_card, cc.sex
from jw_sign_record a
left join jw_sign_record_sport b on b.sign_record_id = a.id
left join jw_sport cc on cc.id = b.sport_id

    and a.team_id = #{teamId}
    and a.game_item_id = #{gameItemId}
    and a.back_number = #{backNumber}

select distinct back_number
from jw_sign_record

    and match_id = #{matchId}
    and team_id = #{teamId}

order by back_number asc

mapper.update:
update jw_sign_record
team_id = #{teamId}, back_number = #{backNumber}, match_id = #{matchId}, game_item_id = #{gameItemId}, sport_limit = #{sportLimit}, works_name = #{worksName}, works_music = #{worksMusic}, works_music_name = #{worksMusicName}, works_video = #{worksVideo}, create_time = #{createTime}, update_time = #{updateTime}, schedule_item_id = #{scheduleItemId}, index_order = #{indexOrder}, all_score = #{allScore}, avg_score = #{avgScore}, rank_order = #{rankOrder}, show_img = #{showImg},
where id = #{id}

mapper.select:
select a.*, jj.judge_name, jsi.item_name, jsi.lock_score, jt.team_name, srs.id as sub_id, srs.match_id as sub_match_id, srs.sport_id as sub_sport_id, srs.sign_record_id as sub_sign_record_id, cc.player_name, cc.id_card, cc.sex, b.id as sub_hai_id, b.sport_id as sub_hai_sport_id, b.judge_id as sub_judge_id, b.score as sub_score, b.score_type as sub_score_type, b.create_time as sub_create_time from jw_sign_record a left join jw_schedule_item jsi on jsi.id = a.schedule_item_id left join jw_hai_score b on b.sport_id = a.id left join jw_judge jj on jj.id = b.judge_id left join jw_team jt on jt.id = a.team_id left join jw_sign_record_sport srs on srs.sign_record_id = a.id left join jw_sport cc on cc.id = srs.sport_id
and a.match_id = #{matchId} and a.game_item_id = #{gameItemId} and a.schedule_item_id = #{scheduleItemId}
order by a.index_order asc

select a.id, a.team_id, a.schedule_item_id, a.index_order, a.back_number, a.match_id, a.game_item_id, a.sport_limit, a.works_name, a.works_music, a.works_music_name, a.works_video, a.create_time, a.update_time, b.id as sub_id, b.match_id as sub_match_id, b.sport_id as sub_sport_id, b.sign_record_id as sub_sign_record_id, cc.player_name, cc.id_card, cc.sex, jt.team_name, jst.schedule_info_id, jst.schedule_place_id, jst.item_name, jst.shcedule_time, jst.area, jsc.score as judgeScore from jw_sign_record a left join jw_sign_record_sport b on b.sign_record_id = a.id left join jw_sport cc on cc.id = b.sport_id left join jw_hai_score jsc on jsc.sport_id = a.id and jsc.judge_id = #{judgeId} left join jw_team jt on jt.id = a.team_id left join jw_schedule_item jst on jst.id = a.schedule_item_id
and a.schedule_item_id = #{scheduleItemId}
order by jt.id
